export type Schema={[key:string]:unknown;type?:'object'|'string'|'number'|'integer'|'boolean'|'array';oneOf?:Schema[];const?:unknown;exclusiveMinimum?:number;minLength?:number;maxLength?:number;pattern?:string;description?:string;properties?:Record<string,Schema>;required?:string[];items?:Schema;enum?:(string|number)[];minimum?:number;maximum?:number;minItems?:number;maxItems?:number;additionalProperties?:Schema|boolean;default?:unknown};
