const operation:Schema={type:'object',description:'Core operation discriminated by `type`. Fields, examples and identity impact: operations.describe {type}. Validated against the full schema before the transaction (unknown fields are rejected with the accepted list).',required:['type'],properties:{type:{type:'string',enum:[...OPERATION_TYPES]}}};
