// Availability is evidence-based: experimental tools work but lack an external end-to-end benchmark or calibration.
const EXPERIMENTAL:Record<string,string>={'variation.branch':'Branches are dry-run drafts; compare them visually before promoting.','variation.compare':'Deterministic evidence only; no aesthetic ranking.','motion.verify':'Sampled geometry only; no visibility, paint, camera or aesthetic judgement.','render.video':'Local ffmpeg preview; no alpha, motion blur, GIF/WebP or part crop yet.','render.motion':'Geometric center traces; not a rendered silhouette or property-channel graph.','render.filmstrip':'Contact sheet from the standalone export (engine fallback); visual judgement is yours.','smoke.emit':'Vector gas parcels with buoyant trajectories; not a CFD solver. Visual tuning required.','fluid.animate':'Flow fields on existing geometry; artistic tuning per asset pending.','motion.spring':'Secondary motion validated on fixtures, not on Candy rigs.','morph.apply':'Topology normalization tested on simple paths.','part.candidates':'Vector promptable segmentation is heuristic; confirm with the human.','expression.rig':'Templates calibrated on fixtures; landmark placement is manual.','critique':'Deterministic checks only; visual judgement is yours.','performance':'Cost model, not measured paint time.','export.capabilities':'Several targets are planned, not implemented.','expression.propose':'Interpretations are heuristic distributions; the human chooses.'};
// MCP destructiveHint: clients ask the human before these. Undo/redo are journaled and reverse each other, so they are not
// destructive (an agent must be able to undo its own transaction); raw ops can delete, dismiss/regenerate drop board options.
const DESTRUCTIVE=new Set(['identity.release','choice.dismiss','ops.apply','choice.regenerate']);
// Every response is an envelope; tools add their own fields. plan.execute returns mai.agent-result/v1.
export const ENVELOPE_SCHEMA:Schema={type:'object',required:['ok'],properties:{ok:{type:'boolean'},tool:{type:'string'},revision:{type:'integer'},error:{type:'object',required:['code','message'],properties:{code:{type:'string'},message:{type:'string'}}}}};
const RESULT_SCHEMA:Schema={type:'object',required:['ok'],properties:{ok:{type:'boolean'},protocol:{type:'string',const:'mai.agent-result/v1'},requestId:{type:'string'},status:{type:'string',enum:['prepared','committed','running','unknown','cancelling']},committed:{type:'boolean'},baseRevision:{type:'integer'},revision:{type:'integer'},snapshotId:{type:'string'},transaction:{type:'object',properties:{id:{type:'string'},undoToken:{type:'string'}}},changes:{type:'array'},identity:{type:'object'},artifacts:{type:'array'},warnings:{type:'array'},error:{type:'object'}}};
for(const t of TOOLS){t.availability=EXPERIMENTAL[t.name]?{status:'experimental',note:EXPERIMENTAL[t.name]}:{status:'stable'};t.destructive=DESTRUCTIVE.has(t.name);t.outputSchema=t.name.startsWith('plan.')?RESULT_SCHEMA:ENVELOPE_SCHEMA;}
export const toolByName=(name:string)=>TOOLS.find(t=>t.name===name||t.mcp===name);
export const CONVENTIONS={workflow:['inspect (scene.inspect / choices.inspect / scene.identity)','plan in your head: map human words → tools; ask only if a part is truly ambiguous','dryRun:true for risky or identity-touching changes','apply with expectedRevision','preview.render and look at the PNGs','identity.check / compare.frames / critique / audit','explain to the human what changed and show previews','iterate on feedback; undo with undoToken if wrong'],
 envelope:'Every response: {ok, tool, revision, …}. Mutations add {operation, target, changes, identityImpact, undoToken, transaction}. Errors: {ok:false, error:{code,message,candidates?,suggestions?,hint?}}.',
 errors:{REVISION_CONFLICT:'Someone edited meanwhile: re-inspect and re-plan.',AMBIGUOUS_TARGET:'Several parts match: show candidates or pick by context; never guess silently.',NOT_FOUND:'No such part: use suggestions or part.candidates.',IDENTITY_BLOCKED:'The change violates a protected part: change approach or ask before identity.release.',INVALID_ARGUMENT:'Fix arguments per schema.',NOT_COMBINABLE:'Board options lack specs: build a new board with explicit ops.',STALE_CHOICE:'Board was rendered for an older revision: regenerate.',UNDO_NOT_LATEST:'Your token is not the latest transaction; inspect history.'},
 identityImpact:{none:'No protected or expressive part touched.',rigid:'Only rigid moves of protected parts.',expression:'Expressive parts deform within the preservation budget.',changed:'Protected/expressive geometry or style changed (should be rare and intentional).'},
 language:'MAI never interprets natural language. You (the agent) map the human\'s words to these tools using inspect results, previews and history.'};
